-- PostGIS の location カラムを更新（PostGIS が有効な場合）
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'postgis') THEN
        UPDATE stores.locations
        SET location = ST_SetSRID(ST_MakePoint(lon, lat), 4326)::geography;
        RAISE NOTICE 'PostGIS location column updated';
    END IF;
END $$;

-- 統計情報
SELECT
    prefecture,
    COUNT(*) as store_count
FROM stores.locations
GROUP BY prefecture
ORDER BY store_count DESC;

SELECT 'Total stores: ' || COUNT(*) as summary FROM stores.locations;
